diff --git a/runtime/nvidia/experiments/w8a16_prefill_staging_probe.cu b/runtime/nvidia/experiments/w8a16_prefill_staging_probe.cu
index 3dd83dcb..5c847a49 100644
--- a/runtime/nvidia/experiments/w8a16_prefill_staging_probe.cu
+++ b/runtime/nvidia/experiments/w8a16_prefill_staging_probe.cu
@@ -19,6 +19,14 @@
     fprintf(stderr, "%s: %s\n", #call, cudaGetErrorString(e)); exit(1); } } while (0)
 using bf16 = __nv_bfloat16;

+__global__ void check_conversion(unsigned* errors) {
+    const unsigned input = blockIdx.x * blockDim.x + threadIdx.x;
+    __half2_raw h = __nv_cvt_fp8x2_to_halfraw2(input, __NV_E4M3);
+    float2 v = __half22float2(*reinterpret_cast<__half2*>(&h));
+    alignas(4) bf16 expected[2] = {__float2bfloat16(v.x), __float2bfloat16(v.y)};
+    if (pgm90_fp8_bf16_pair(input) != *(unsigned*)expected) atomicAdd(errors, 1u);
+}
+
 __global__ void gemm(bf16* c, const bf16* a, const uint8_t* b,
                      const float* scale, unsigned m, unsigned n, unsigned k) {
     extern __shared__ bf16 arena[];
@@ -35,6 +43,16 @@ template<class T> T* device(const std::vector<T>& host) {
 int main(int argc, char** argv) {
     if (argc != 2) return 2;
     const int repeats = std::getenv("PLOW_STAGING_CHECK_ONLY") ? 0 : 7;
+    const bool dense_weights = std::getenv("PLOW_STAGING_DENSE_WEIGHTS");
+    unsigned* errors;
+    CHECK(cudaMalloc(&errors, sizeof(unsigned)));
+    CHECK(cudaMemset(errors, 0, sizeof(unsigned)));
+    check_conversion<<<256,256>>>(errors);
+    unsigned mismatches;
+    CHECK(cudaMemcpy(&mismatches, errors, sizeof(unsigned), cudaMemcpyDeviceToHost));
+    CHECK(cudaFree(errors));
+    if (mismatches) { fprintf(stderr,"conversion mismatches=%u\n",mismatches); return 1; }
+    printf("All 65536 E4M3 pairs bit-exact against CUDA conversion\n");
     const unsigned smem = PGM_ARENA_BF16 * sizeof(bf16);
     CHECK(cudaFuncSetAttribute(gemm, cudaFuncAttributeMaxDynamicSharedMemorySize, smem));
     for (unsigned m : {128u, 512u, 1024u, 2048u}) {
@@ -49,7 +67,10 @@ int main(int argc, char** argv) {
             std::vector<uint8_t> b(size_t(n)*k);
             std::vector<float> scale(n);
             for (auto& x : a) x = __float2bfloat16(int(rng()%7)-3);
-            for (auto& x : b) { __nv_fp8_e4m3 q(float(int(rng()%13)-6)); x = *(uint8_t*)&q; }
+            for (auto& x : b) {
+                const int value = dense_weights ? int(rng()%799)-399 : int(rng()%13)-6;
+                __nv_fp8_e4m3 q{float(value)}; x = *(uint8_t*)&q;
+            }
             for (unsigned j=0; j<n; ++j) scale[j] = std::ldexp(1.f, -5 + int(j%3));
             auto* da=device(a); auto* db=device(b); auto* ds=device(scale); auto* dc=device(c);
             auto launch = [&] { gemm<<<132,256,smem>>>(dc,da,db,ds,m,n,k); CHECK(cudaGetLastError()); };
diff --git a/runtime/nvidia/op_gemm_sm90.cuh b/runtime/nvidia/op_gemm_sm90.cuh
index 468c5874..ff719383 100644
--- a/runtime/nvidia/op_gemm_sm90.cuh
+++ b/runtime/nvidia/op_gemm_sm90.cuh
@@ -172,6 +172,21 @@ __device__ __forceinline__ void pgm90_stage_fp8(uint8_t* dst, const uint8_t* __r
 #ifndef PLOW_NV_W8A16_PREFETCH
 #define PLOW_NV_W8A16_PREFETCH 0
 #endif
+#ifndef PLOW_NV_W8A16_BITS
+#define PLOW_NV_W8A16_BITS 0
+#endif
+__device__ __forceinline__ unsigned pgm90_fp8_bf16_pair(unsigned short input) {
+    if ((input & 0x0078) && (input & 0x7800)
+        && (input & 0x007f) != 0x007f && (input & 0x7f00) != 0x7f00) {
+        const unsigned expanded = __byte_perm(input, 0, 0x4140);
+        return (((expanded & 0x007f007f) << 4) + 0x3c003c00)
+            | ((expanded & 0x00800080) << 8);
+    }
+    __half2_raw h = __nv_cvt_fp8x2_to_halfraw2(input, __NV_E4M3);
+    float2 v = __half22float2(*reinterpret_cast<__half2*>(&h));
+    alignas(4) __nv_bfloat16 result[2] = {__float2bfloat16(v.x), __float2bfloat16(v.y)};
+    return *(const unsigned*)result;
+}
 __device__ __forceinline__ void pgm90_stage_bf16(__nv_bfloat16* dst,
                                                  const uint8_t* __restrict__ src, int tid,
                                                  int rows, int row0, int kbase, int R, int K) {
@@ -194,10 +209,14 @@ __device__ __forceinline__ void pgm90_stage_bf16(__nv_bfloat16* dst,
             alignas(16) __nv_bfloat16 values[8];
 #pragma unroll
             for (int j = 0; j < 4; ++j) {
+#if PLOW_NV_W8A16_BITS
+                ((unsigned*)values)[j] = pgm90_fp8_bf16_pair(w[j]);
+#else
                 __half2_raw h = __nv_cvt_fp8x2_to_halfraw2((__nv_fp8x2_storage_t)w[j], __NV_E4M3);
                 float2 v = __half22float2(*reinterpret_cast<__half2*>(&h));
                 values[2 * j] = __float2bfloat16(v.x);
                 values[2 * j + 1] = __float2bfloat16(v.y);
+#endif
             }
             *(uint4*)(dst + sm90_swz_off<PGM90_BK, 8>(L / PGM90_CH, L % PGM90_CH))
                 = *(const uint4*)values;
